import{_ as e,o as a,c as r,a5 as h}from"./chunks/framework.bIR-4glx.js";const c=JSON.parse('{"title":"证据链模板","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/evidence-chain.zh.md","filePath":"public/downloads/worksheets/evidence-chain.zh.md","lastUpdated":1795488252000}'),d={name:"public/downloads/worksheets/evidence-chain.zh.md"};function o(n,t,b,i,l,p){return a(),r("div",null,[...t[0]||(t[0]=[h('<h1 id="证据链模板" tabindex="-1">证据链模板 <a class="header-anchor" href="#证据链模板" aria-label="Permalink to &quot;证据链模板&quot;">​</a></h1><p>这张表用来回答一个具体问题：<strong>我究竟知道自己改变了什么？</strong></p><p>它不要求所有结果都变好，也不把生活压缩成分数。它只把同一任务在不同条件下的样本放在一起，让你分清“当下做得到”“过几天还记得”“换个地方仍能使用”分别有什么证据。</p><p>复制到自己的私有笔记，每个主问题使用一份。不要写入密码、证件、客户资料、医疗隐私或未获授权的第三方信息。涉及健康、安全、法律、财务或持续失控时，先联系可信任的人和合格的专业人士。</p><h2 id="_1-先定义要回答的问题" tabindex="-1">1. 先定义要回答的问题 <a class="header-anchor" href="#_1-先定义要回答的问题" aria-label="Permalink to &quot;1. 先定义要回答的问题&quot;">​</a></h2><p>记录开始日期：<br> 真实场景与受众/用户：<br> 本次只回答的问题：<br> 完成标准：<br> 可能的风险与停止条件：</p><p>问题要能被观察，例如“我能否在没有稿件的情况下，用英语说明项目风险并回答一个追问？”不要写“我是否变得更好”。</p><h2 id="_2-保存未经修饰的基线" tabindex="-1">2. 保存未经修饰的基线 <a class="header-anchor" href="#_2-保存未经修饰的基线" aria-label="Permalink to &quot;2. 保存未经修饰的基线&quot;">​</a></h2><p>基线应尽量发生在 AI、同伴反馈或集中训练之前。记录条件，避免把工具、额外时间和熟悉材料藏进比较里。</p><table tabindex="0"><thead><tr><th>日期</th><th>任务与限制</th><th>是否使用工具</th><th>结果/错误</th><th>原始证据位置</th></tr></thead><tbody><tr><td></td><td></td><td>否</td><td></td><td></td></tr></tbody></table><p>我在基线时能够独立完成什么：<br> 我在哪里停住或需要提示：<br> 基线不能说明什么：</p><h2 id="_3-记录即时表现" tabindex="-1">3. 记录即时表现 <a class="header-anchor" href="#_3-记录即时表现" aria-label="Permalink to &quot;3. 记录即时表现&quot;">​</a></h2><p>即时表现说明这一次在当前条件下发生了什么，不自动说明能力已经稳定。</p><table tabindex="0"><thead><tr><th>日期</th><th>条件与提示</th><th>完成了什么</th><th>质量/用时/返工</th><th>证据位置</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>如果使用 AI，请写清它做了什么，以及关闭 AI 后你独立完成了什么。聊天记录可以作为过程痕迹，不能单独作为能力证明。</p><h2 id="_4-做一次延迟保持" tabindex="-1">4. 做一次延迟保持 <a class="header-anchor" href="#_4-做一次延迟保持" aria-label="Permalink to &quot;4. 做一次延迟保持&quot;">​</a></h2><p>等待一段时间，撤掉最近的提示和原答案，再完成相近任务。时间间隔按任务和个人容量决定，但必须写清楚。</p><p>复测日期：<br> 距离上次练习：<br> 撤掉了哪些提示：<br> 相近任务：<br> 独立结果：<br> 仍然出现的错误：<br> 证据位置：</p><h2 id="_5-做一次迁移" tabindex="-1">5. 做一次迁移 <a class="header-anchor" href="#_5-做一次迁移" aria-label="Permalink to &quot;5. 做一次迁移&quot;">​</a></h2><p>保留核心动作，改变至少一个条件：主题、听众、时间限制、材料、工具权限或任务目的。</p><table tabindex="0"><thead><tr><th>改变的条件</th><th>新任务</th><th>独立结果</th><th>对方/用户如何理解</th><th>证据位置</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>迁移失败不等于前面的练习没有价值。它说明你需要降低变化幅度、补充前置知识，或重新定义完成标准。</p><h2 id="_6-把事实、解释和假设分开" tabindex="-1">6. 把事实、解释和假设分开 <a class="header-anchor" href="#_6-把事实、解释和假设分开" aria-label="Permalink to &quot;6. 把事实、解释和假设分开&quot;">​</a></h2><p>事实：我能指出日期、条件、样本、来源或直接观察。<br> 解释：我如何理解这些事实；它可能需要修正。<br> 假设：我准备在下一项行动中检验的判断。<br> 不能推出的结论：</p><p>例如，“独立版在 90 秒内完成”是记录；“因为睡眠变好所以表达更清楚”是解释；“下周换一个陌生听众仍能完成，才说明改动可能有效”是待验证假设。</p><h2 id="_7-让证据决定下一步" tabindex="-1">7. 让证据决定下一步 <a class="header-anchor" href="#_7-让证据决定下一步" aria-label="Permalink to &quot;7. 让证据决定下一步&quot;">​</a></h2><p>这条证据最支持：继续 / 降档 / 改变变量 / 暂停或停止<br> 我只改变的一个条件：<br> 下一项最小任务：<br> 下一项任务的完成标准：<br> 需要的支持、授权或专业判断：<br> 下一次复查日期：</p><p>如果证据互相冲突，不要用平均数掩盖冲突。先写出不同条件，再决定要不要补一次样本。证据不足时，缩小问题通常比制造一个精确分数更诚实。</p><h2 id="_8-交接摘要" tabindex="-1">8. 交接摘要 <a class="header-anchor" href="#_8-交接摘要" aria-label="Permalink to &quot;8. 交接摘要&quot;">​</a></h2><p>主问题与完成标准：<br> 最可靠的证据：<br> 最不可靠或仍缺少的证据：<br> 重复出现的错误/风险：<br> 下一项最小任务与停止条件：<br> 证据文件夹或链接：</p><p>把这段摘要交给未来的自己、同伴或 AI 时，要求对方只根据这份记录工作，不要假装记得其他会话，也不要补写不存在的事实。</p><p>相关章节：<a href="https://byoungd.github.io/up/threads/part-3/5-evidence-and-transfer" target="_blank" rel="noreferrer">证据篇：变化要如何被看见</a> ｜ <a href="https://byoungd.github.io/up/templates/toolkit" target="_blank" rel="noreferrer">工具箱总览</a> ｜ <a href="https://byoungd.github.io/up/templates/rhythm-ledger" target="_blank" rel="noreferrer">节律账本</a> ｜ <a href="https://byoungd.github.io/up/reference/glossary" target="_blank" rel="noreferrer">术语与方法索引</a></p><hr><p>来源：<a href="https://byoungd.github.io/up/templates/evidence-chain" target="_blank" rel="noreferrer">人生进阶指南</a> · 稿件更新：2026-09-01。内容许可：<a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>。</p>',34)])])}const _=e(d,[["render",o]]);export{c as __pageData,_ as default};
